/bin/zsh -lc "node <<'NODE'
const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
const ids = ['simulation','speed','columns','rows','layers','mass','speedValue','columnsValue','rowsValue','layersValue','massValue','testButton','resetButton','telemetrySpeed','telemetryTime','telemetryBricks','telemetryMass','statusText'];
const elements = new Map();
const listeners = new Map();
for (const id of ids) {
  const el = { id, value: ({speed:'22',columns:'12',rows:'8',layers:'2',mass:'2.5'}[id] || ''), min: ({speed:'5',columns:'4',rows:'3',layers:'1',mass:'0.5'}[id] || ''), max: ({speed:'45',columns:'24',rows:'16',layers:'5',mass:'12'}[id] || ''), style: { setProperty() {} }, addEventListener(type, cb) { listeners.set("'`${id}:${type}`, cb); }, getBoundingClientRect() { return { width: 1200, height: 780 }; } };
  if (id === '"'simulation') {
    const noop = () => {};
    const gradient = () => ({ addColorStop: noop });
    el.getContext = () => new Proxy({ createLinearGradient: gradient, createRadialGradient: gradient }, { get(target, prop) { if ("'!(prop in target)) target[prop] = noop; return target[prop]; }, set(target, prop, value) { target[prop] = value; return true; } });
  }
  elements.set(id, el);
}
const rafs = [];
const context = {
  console,
  document: { getElementById(id) { return elements.get(id); } },
  window: { devicePixelRatio: 1, addEventListener() {} },
  performance: { now: () => 0 },
  requestAnimationFrame(cb) { rafs[0] = cb; return 1; },
  Math, Number, String, Object, Array, Infinity, NaN, parseFloat, parseInt, Date
};
vm.createContext(context);
vm.runInContext(script, context, { timeout: 1000 });
if (!listeners.has('"'testButton:click')) throw new Error('Test handler missing');
listeners.get('testButton:click')();
let now = 0;
for (let i = 0; i < 900; i++) { now += 1000 / 60; rafs[0](now); }
console.log('runtime-ok');
console.log('status', elements.get('statusText').textContent);
console.log('telemetry', elements.get('telemetrySpeed').innerHTML, elements.get('telemetryTime').innerHTML, elements.get('telemetryBricks').innerHTML);
NODE"

